/* void is the default mode */
:root {
  color-scheme: dark;
  --ground: oklch(17% 0.035 275);
  --ground-deep: oklch(13% 0.03 280);
  --surface: oklch(20% 0.035 278);
  --line: oklch(30% 0.03 278);
  --line-strong: oklch(50% 0.03 278);
  --ink: oklch(94% 0.01 85);
  --ink-muted: oklch(76% 0.02 275);
  --ink-dim: oklch(66% 0.015 275);
  --ink-dim-ui: oklch(64% 0.02 275);
  --thread: oklch(75% 0.13 55);
  --thread-bright: oklch(84% 0.12 65);
  --thread-ink: oklch(13% 0.03 280);
  --thread-soft: oklch(75% 0.13 55 / 0.13);
  --atmosphere-wash: oklch(45% 0.09 300);
  --atmosphere: oklch(62% 0.12 300);
  --danger: oklch(64% 0.19 25);
  --danger-soft: oklch(64% 0.19 25 / 0.13);
  --atmosphere-soliton: oklch(55% 0.11 300);
  --atmosphere-orbit: oklch(60% 0.10 260);
  --atmosphere-hyperspeed: oklch(65% 0.10 200);
  --radius-xs: 6px;
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-pill: 20px;
  --radius-full: 9999px;
  --space-xs: 4px;
  --space-sm: 8px;
  --space-md: 12px;
  --space-lg: 16px;
  --space-xl: 24px;
  --space-2xl: 32px;
  --space-3xl: 48px;
  --space-4xl: 64px;
  --space-measure: 42rem;
  --font-display-xl: "Panchang", ui-sans-serif, system-ui, sans-serif;
  --text-display-xl: clamp(1.85rem, 4.5vw + 0.85rem, 2.9rem);
  --weight-display-xl: 800;
  --leading-display-xl: 1.1;
  --tracking-display-xl: -0.02em;
  --font-display-lg: "Panchang", ui-sans-serif, system-ui, sans-serif;
  --text-display-lg: 1.2rem;
  --weight-display-lg: 600;
  --leading-display-lg: 1.2;
  --tracking-display-lg: -0.01em;
  --font-display-ui: "Panchang", ui-sans-serif, system-ui, sans-serif;
  --text-display-ui: 15px;
  --weight-display-ui: 600;
  --leading-display-ui: 1.3;
  --tracking-display-ui: -0.015em;
  --font-body: "Supreme", ui-sans-serif, system-ui, sans-serif;
  --text-body: 1.0625rem;
  --weight-body: 400;
  --leading-body: 1.65;
  --font-body-strong: "Supreme", ui-sans-serif, system-ui, sans-serif;
  --text-body-strong: 1.0625rem;
  --weight-body-strong: 500;
  --leading-body-strong: 1.65;
  --font-reading: "Erode", Charter, "Iowan Old Style", Georgia, serif;
  --text-reading: 1.125rem;
  --weight-reading: 400;
  --leading-reading: 1.65;
  --font-meta: "Fragment Mono", ui-monospace, "SF Mono", Menlo, monospace;
  --text-meta: 0.8rem;
  --weight-meta: 400;
  --leading-meta: 1.4;
  --font-label: "Fragment Mono", ui-monospace, "SF Mono", Menlo, monospace;
  --text-label: 11px;
  --weight-label: 400;
  --leading-label: 1.3;
  --tracking-label: 0.14em;
  --ease-drift: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-snap: cubic-bezier(0.22, 1, 0.36, 1);
}

[data-mode="paper"] {
  color-scheme: light;
  --ground: #fbfaf7;
  --ground-deep: #fbfaf7;
  --surface: #f4f2ed;
  --line: #d9d5cc;
  --line-strong: #898276;
  --ink: #1a1a1a;
  --ink-muted: #55524c;
  --ink-dim: #6f6a62;
  --ink-dim-ui: #6f6a62;
  --thread: oklch(55% 0.13 55);
  --thread-bright: oklch(48% 0.14 52);
  --thread-soft: oklch(94% 0.035 60);
  --thread-ink: #fbfaf7;
  --danger: #735853;
  --danger-soft: #efe9e7;
}

